mapper.select:
/* Subcon02Mapper.selectMenuButtonAuthCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SYST_AUTH_MENU
     WHERE CMPNY_CD  = #{cmpnyCd}
       AND AUTH_CD   = #{authCd}
       AND MENU_D_ID = #{menuDId}
       AND USE_YN    = 'Y'

           AND BTN_SRCH = 'Y'
           AND BTN_NEW = 'Y'
           AND BTN_SAVE = 'Y'
           AND BTN_DELT = 'Y'
           AND 1 = 0

     LIMIT 1
) T

/* Subcon02Mapper.selectMySiteActiveCnt */
SELECT COUNT(*)
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND IFNULL(A.USE_YN, 'Y') = 'Y'

/* Subcon02Mapper.selectSiteLinkSrc */
SELECT
    A.LINK_SRC_CMPNY_CD     AS linkSrcCmpnyCd
    , A.LINK_SRC_SITE_CD    AS linkSrcSiteCd
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}

/* Subcon02Mapper.selectActiveLinkCntForUpdate */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SITE_LINK
     WHERE STATUS IN ('PROPOSED', 'ACTIVE')
       AND SRC_CMPNY_CD = #{srcCmpnyCd}
       AND SRC_SITE_CD  = #{srcSiteCd}
       AND DST_CMPNY_CD = #{dstCmpnyCd}
     FOR UPDATE
) T

mapper.insert:
/* Subcon02Mapper.insertSiteLink */
INSERT INTO TB_SITE_LINK (
      RELATION_ID
    , SRC_CMPNY_CD
    , SRC_SITE_CD
    , DST_CMPNY_CD
    , STATUS
    , PROPOSE_USER_CD
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{relationId}
    , #{srcCmpnyCd}
    , #{srcSiteCd}
    , #{dstCmpnyCd}
    , 'PROPOSED'
    , #{proposeUserCd}
    , #{insertNo}
    , NOW()
)

mapper.update:
/* Subcon02Mapper.acceptSiteLinkPreempt */
UPDATE TB_SITE_LINK L
   SET L.STATUS           = 'ACTIVE'
     , L.PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , L.PROCESS_USER_CD  = #{actorUserCd}
     , L.PROCESS_DTIME    = NOW()
     , L.PROCESS_COMMENT  = #{comment}
     , L.UPDATE_NO        = #{actorUserCd}
     , L.UPDATE_DATE      = NOW()
 WHERE L.LINK_ID      = #{linkId}
   AND L.STATUS       = 'PROPOSED'
   AND L.DST_CMPNY_CD = #{actorCmpnyCd}
   AND EXISTS (
        SELECT 1
          FROM TB_CMPNY_RELATION R
         WHERE R.RELATION_ID = L.RELATION_ID
           AND R.STATUS      = 'ACCEPTED'
   )

/* Subcon02Mapper.rejectSiteLink */
UPDATE TB_SITE_LINK
   SET STATUS           = 'REJECTED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE LINK_ID      = #{linkId}
   AND STATUS       = 'PROPOSED'
   AND DST_CMPNY_CD = #{actorCmpnyCd}

/* Subcon02Mapper.cancelSiteLink */
UPDATE TB_SITE_LINK
   SET STATUS           = 'CANCELLED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE LINK_ID      = #{linkId}
   AND STATUS       = 'PROPOSED'
   AND SRC_CMPNY_CD = #{actorCmpnyCd}

/* Subcon02Mapper.terminateSiteLink */
UPDATE TB_SITE_LINK
   SET STATUS           = 'TERMINATED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE LINK_ID = #{linkId}
   AND STATUS  = 'ACTIVE'
   AND (SRC_CMPNY_CD = #{actorCmpnyCd} OR DST_CMPNY_CD = #{actorCmpnyCd})

