/* Subcon02Mapper.selectSiteSrcRaw */
SELECT
    A.SITE_NO       AS siteNo
    , A.SITE_NM     AS siteNm
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}

/* Subcon02Mapper.selectSiteNoDupCnt */
SELECT COUNT(*)
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_NO  = #{siteNo}

