/* Subcon02Mapper.insertMirrorRootNode */
INSERT INTO TB_SITE_NODE (
      CMPNY_CD
    , SITE_CD
    , NODE_CD
    , NODE_NM
    , NODE_TYPE
    , SELF_ATTD_APPRV_YN
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
) VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , 'n1'
    , #{nodeNm}
    , '00001'
    , 'Y'
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

mapper.update:
/* Subcon02Mapper.updateSiteLinkDstSite */
UPDATE TB_SITE_LINK
   SET DST_SITE_CD  = #{dstSiteCd}
     , UPDATE_NO    = #{updateNo}
     , UPDATE_DATE  = NOW()
 WHERE LINK_ID = #{linkId}

/* Subcon02Mapper.clearSiteLinkSrc */
UPDATE TB_SITE
   SET LINK_SRC_CMPNY_CD = NULL
     , LINK_SRC_SITE_CD  = NULL
     , UPDATE_NO         = #{updateNo}
     , UPDATE_DATE       = NOW()
 WHERE CMPNY_CD = #{dstCmpnyCd}
   AND SITE_CD  = #{dstSiteCd}
   AND LINK_SRC_CMPNY_CD = #{srcCmpnyCd}

/* Subcon02Mapper.clearSchLinkSrc */
UPDATE TB_SCH_MGMT
   SET LINK_SRC_CMPNY_CD = NULL
     , LINK_SRC_SCH_CD   = NULL
     , UPDATE_NO         = #{updateNo}
     , UPDATE_DATE       = NOW()
 WHERE CMPNY_CD = #{dstCmpnyCd}
   AND SITE_CD  = #{dstSiteCd}
   AND LINK_SRC_CMPNY_CD = #{srcCmpnyCd}

/* Subcon02Mapper.terminateSiteLinkBySystem */
UPDATE TB_SITE_LINK
   SET STATUS           = 'TERMINATED'
     , PROCESS_USER_CD  = #{actionUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = '관계 해지에 따른 자동 독립화'
     , UPDATE_NO        = #{actionUserCd}
     , UPDATE_DATE      = NOW()
 WHERE LINK_ID = #{linkId}
   AND STATUS  = 'ACTIVE'

/* Subcon02Mapper.cancelSiteLinkBySystem */
UPDATE TB_SITE_LINK
   SET STATUS           = 'CANCELLED'
     , PROCESS_USER_CD  = #{actionUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = '관계 해지에 따른 자동 취소'
     , UPDATE_NO        = #{actionUserCd}
     , UPDATE_DATE      = NOW()
 WHERE LINK_ID = #{linkId}
   AND STATUS  = 'PROPOSED'

/* Subcon02Mapper.propagateMirrorSite */
UPDATE TB_SITE D
    INNER JOIN TB_SITE S
        ON (
            S.CMPNY_CD = #{srcCmpnyCd}
        AND S.SITE_CD  = #{srcSiteCd}
        )
   SET D.SITE_NM     = S.SITE_NM
     , D.ADDR_1      = S.ADDR_1
     , D.ADDR_2      = S.ADDR_2
     , D.ZIP_CODE    = S.ZIP_CODE
     , D.STR_DATE    = S.STR_DATE
     , D.END_DATE    = S.END_DATE
     , D.USE_YN      = S.USE_YN
     , D.TEL_NO      = S.TEL_NO
     , D.GPS_RANGE   = S.GPS_RANGE
     , D.SITE_DESC   = S.SITE_DESC
     , D.LAT         = S.LAT
     , D.LON         = S.LON
     , D.UPDATE_NO   = 'SYSTEM'
     , D.UPDATE_DATE = NOW()
 WHERE D.CMPNY_CD = #{dstCmpnyCd}
   AND D.SITE_CD  = #{dstSiteCd}
   AND D.LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
   AND D.LINK_SRC_SITE_CD  = #{srcSiteCd}

